using DriveOS.Modules.CurriculumPedagogy.Domain.RemediationPlans;using DriveOS.SharedKernel.Identifiers;using Xunit;
namespace DriveOS.UnitTests.Modules.CurriculumPedagogy.RemediationPlans;
public sealed class RemediationPlanTests{[Fact]public void Plan_requires_target_before_activation(){var now=DateTimeOffset.UtcNow;var r=RemediationPlan.Create(RemediationPlanId.New(),new OrganizationId(Guid.NewGuid()),new PersonId(Guid.NewGuid()),new TrainingPathId(Guid.NewGuid()),new UserId(Guid.NewGuid()),null,"Renforcer les contrôles visuels",2m,2,DateOnly.FromDateTime(now.AddDays(7).UtcDateTime),now);Assert.True(r.IsSuccess);Assert.True(r.Value.Activate(now).IsFailure);var add=r.Value.AddTarget(RemediationPlanTargetId.New(),new CompetencyId(Guid.NewGuid()),"Stabiliser l'observation aux intersections");Assert.True(add.IsSuccess);Assert.True(r.Value.Activate(now).IsSuccess);Assert.Equal(RemediationPlanStatus.Active,r.Value.Status);}[Fact]public void Duplicate_competency_is_rejected(){var now=DateTimeOffset.UtcNow;var r=RemediationPlan.Create(RemediationPlanId.New(),new OrganizationId(Guid.NewGuid()),new PersonId(Guid.NewGuid()),new TrainingPathId(Guid.NewGuid()),new UserId(Guid.NewGuid()),null,"Plan",null,1,DateOnly.FromDateTime(now.AddDays(1).UtcDateTime),now).Value;var c=new CompetencyId(Guid.NewGuid());Assert.True(r.AddTarget(RemediationPlanTargetId.New(),c,"Objectif 1").IsSuccess);Assert.True(r.AddTarget(RemediationPlanTargetId.New(),c,"Objectif 2").IsFailure);}}
